package mx.com.mesaregia.inventario.application.service.impl;
import mx.com.mesaregia.inventario.application.service.MovimientoInventarioQueryService; import mx.com.mesaregia.inventario.api.response.*; import mx.com.mesaregia.inventario.domain.enums.TipoMovimiento; import mx.com.mesaregia.inventario.mapper.InventarioMapper; import mx.com.mesaregia.inventario.repository.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime;
@Service
public class MovimientoInventarioQueryServiceImpl implements MovimientoInventarioQueryService { private final MovimientoInventarioRepository repo; public MovimientoInventarioQueryServiceImpl(MovimientoInventarioRepository r){repo=r;} @Override @Transactional(readOnly=true) public PageResponse<MovimientoResponse> buscar(Long p,Long o,TipoMovimiento t,LocalDateTime d,LocalDateTime h,Pageable page){return PageResponse.from(repo.findAll(MovimientoSpecifications.filtros(p,o,t,d,h),page).map(InventarioMapper::movimiento));} }
